class Shape {
  constructor(color) {
    this.color = color
  }
  getColor() {
    return this.color
  }
}
class Circle extends Shape {
  constructor(color, radius) {
    super(color)
    this.radius = radius
  }
  area() {
    return Math.PI * this.radius ** 2
  }
}
let c = new Circle('红色', 5)
console.log(c.getColor())
console.log(c.area())

